 [['pyramid3',4],['squarepyramid',5],['triprism',6],['cube',8],['cuboid',8],['cylinder',0]].forEach(([t,v],i)=>{one('41-q2-'+i+'-name','4.1 · 2 · Shape '+(i+1)+' name',mathNameAliases(t));one('41-q2-'+i+'-vertices','4.1 · 2 · Shape '+(i+1)+' vertices',v);});
 ['cylinder','cube','pyramid','hexprism'].forEach((t,i)=>{one('41-q3a-'+i+'-name','4.1 · 3a · Shape '+(i+1)+' name',t==='hexprism'?[...mathNameAliases('hexprism'),'octagonal prism','prism']:mathNameAliases(t));review('41-q3a-'+i,'4.1 · 3a · Trace shape '+(i+1),true);});review('41-q3b','4.1 · 3b/c · Two shapes, at least one prism, with ticks',true);
 ['Cube','Cuboid','Sphere','Prism','Pyramid','cylinder'].forEach((name,i)=>review('41-q4-'+i,'4.1 · 4 · Your '+name+' example',true));review('41-q4-blocks','4.1 · 4 · Building blocks');review('41-q4-choice1','4.1 · 4 · First shape to make');review('41-q4-choice2','4.1 · 4 · Second shape to make');
 ['prism','prism','pyramid','prism','pyramid','prism'].forEach((type,i)=>one('41-q5-'+'abcdef'[i]+'-name','4.1 · 5'+'abcdef'[i],mathNameAliases(type)));
 ['cube','cuboid','cylinder','sphere'].forEach((type,i)=>{one('41-q6-'+i+'-name','4.1 · 6'+'abcd'[i]+' · Name',mathNameAliases(type));review('41-q6-'+i,'4.1 · 6'+'abcd'[i]+' · Drawing',true);});review('41-q7-cube','4.1 · 7 · Cube sketch',true);review('41-q7-cuboid','4.1 · 7 · Cuboid sketch',true);
